import os,re
mods={}
for dp,_,fns in os.walk('AlgebraicJacobian'):
    for fn in fns:
        if fn.endswith('.lean'):
            p=os.path.join(dp,fn); mods[p[:-5].replace('/','.')]=p
imports={}; umb=set()
for n,p in mods.items():
    ds=[]
    for line in open(p,errors='replace'):
        m=re.match(r'^import\s+([A-Za-z0-9_.]+)',line)
        if m:
            d=m.group(1)
            if d=='Mathlib': umb.add(n)
            elif d.startswith('AlgebraicJacobian'): ds.append(d)
    imports[n]=ds
memo={}
def cont(m):
    if m in memo: return memo[m]
    memo[m]=True
    r = m in umb or any(cont(d) for d in imports.get(m,[]))
    memo[m]=r; return r
ready=[m for m in umb if not any(cont(d) for d in imports[m])]
ready.sort(key=lambda m: os.path.getsize(mods[m]))
for m in ready: print(mods[m])
